function getHealthStatus(score) {
  if (score >= 75) return "healthy";
  if (score >= 50) return "warning";
  return "at-risk";
}
function getHealthColor(score) {
  if (score >= 75) return "text-emerald-400";
  if (score >= 50) return "text-amber-400";
  return "text-red-400";
}
function getHealthBgColor(score) {
  if (score >= 75)
    return "bg-emerald-500/20 text-emerald-300 border-emerald-500/30";
  if (score >= 50) return "bg-amber-500/20 text-amber-300 border-amber-500/30";
  return "bg-red-500/20 text-red-300 border-red-500/30";
}
function getHealthArcColor(score) {
  if (score >= 75) return "#10b981";
  if (score >= 50) return "#f59e0b";
  return "#ef4444";
}
function getStatusLabel(score) {
  if (score >= 75) return "Healthy";
  if (score >= 50) return "Needs Attention";
  return "At Risk";
}
function getComponentStatus(score) {
  if (score >= 70) return "good";
  if (score >= 45) return "warning";
  return "critical";
}
function calcLeadsScore(leads) {
  let score = 40;
  const activeLeads = leads.filter(
    (l2) => l2.status === "new" || l2.status === "contacted" || l2.status === "qualified"
  );
  score += Math.min(activeLeads.length * 5, 25);
  const closed = leads.filter((l2) => l2.status === "closed").length;
  const total = leads.length;
  if (total > 0) {
    const rate = closed / total;
    score += Math.round(rate * 35);
  }
  return Math.min(score, 100);
}
function calcReputationScore(reviews) {
  let score = 30;
  score += Math.min(reviews.length * 2, 30);
  if (reviews.length > 0) {
    const avg = reviews.reduce((s2, r2) => s2 + r2.rating, 0) / reviews.length;
    if (avg >= 4.5) score += 30;
    else if (avg >= 4) score += 20;
    else if (avg >= 3.5) score += 10;
  }
  const hasResponded = reviews.some(
    (r2) => r2.sentiment === "responded" || reviews.length > 2
  );
  if (hasResponded) score += 10;
  return Math.min(score, 100);
}
function calcAgentScore(tenantId, subs) {
  const active = subs.filter(
    (s2) => s2.tenantId === tenantId && s2.status === "active"
  ).length;
  if (active === 0) return 25;
  if (active === 1) return 60;
  if (active === 2) return 80;
  return 100;
}
function calcWebsiteScore(audit) {
  if (!audit) return 50;
  const {
    seoScore,
    technicalScore,
    contentScore,
    conversionScore,
    gmb,
    website,
    citations,
    backlinks,
    total
  } = audit;
  if (seoScore !== void 0 && technicalScore !== void 0 && contentScore !== void 0 && conversionScore !== void 0) {
    return Math.round(
      (seoScore + technicalScore + contentScore + conversionScore) / 4
    );
  }
  if (total !== void 0) return total;
  const vals = [gmb, website, citations, backlinks].filter(
    (v2) => v2 !== void 0
  );
  if (vals.length > 0)
    return Math.round(vals.reduce((a2, b2) => a2 + b2, 0) / vals.length);
  return 50;
}
function generateRecommendations(leadsScore, reputationScore, agentScore, websiteScore) {
  const recs = [
    {
      score: leadsScore,
      text: "Follow up with leads in 'contacted' stage to move them through the pipeline"
    },
    {
      score: reputationScore,
      text: "Request reviews from recent customers to boost your rating average"
    },
    {
      score: agentScore,
      text: "Consider activating an AI agent to automate lead handling and booking"
    },
    {
      score: websiteScore,
      text: "Your website audit score is low — improve SEO and conversion elements"
    }
  ];
  return recs.sort((a2, b2) => a2.score - b2.score).slice(0, 3).map((r2) => r2.text);
}
function calculateHealthScore(tenantId, data) {
  const { leads, reviews, auditScore, agentSubscriptions } = data;
  const leadsScore = calcLeadsScore(leads);
  const reputationScore = calcReputationScore(reviews);
  const agentScore = calcAgentScore(tenantId, agentSubscriptions);
  const websiteScore = calcWebsiteScore(auditScore);
  const overallScore = Math.round(
    leadsScore * 0.3 + reputationScore * 0.25 + agentScore * 0.25 + websiteScore * 0.2
  );
  const components = [
    {
      factor: "leads",
      weight: 30,
      rawScore: leadsScore,
      weightedScore: Math.round(leadsScore * 0.3),
      displayLabel: "Leads & Pipeline",
      status: getComponentStatus(leadsScore)
    },
    {
      factor: "reputation",
      weight: 25,
      rawScore: reputationScore,
      weightedScore: Math.round(reputationScore * 0.25),
      displayLabel: "Reputation & Reviews",
      status: getComponentStatus(reputationScore)
    },
    {
      factor: "agents",
      weight: 25,
      rawScore: agentScore,
      weightedScore: Math.round(agentScore * 0.25),
      displayLabel: "AI Agents Active",
      status: getComponentStatus(agentScore)
    },
    {
      factor: "website",
      weight: 20,
      rawScore: websiteScore,
      weightedScore: Math.round(websiteScore * 0.2),
      displayLabel: "Website & SEO",
      status: getComponentStatus(websiteScore)
    }
  ];
  const recommendations = generateRecommendations(
    leadsScore,
    reputationScore,
    agentScore,
    websiteScore
  );
  return {
    tenantId,
    overallScore,
    leadsScore,
    reputationScore,
    agentScore,
    websiteScore,
    components,
    trend: "stable",
    lastUpdated: Date.now(),
    recommendations
  };
}
