function buildAdminExplanation(lead, score, frameworks) {
  const { recommended_offer_angle, score_tier, top_audit_signals } = score;
  const ANGLE_EXPLANATIONS = {
    visibility_gap: "This business scores low on search discoverability. The angle leads with the visibility gap because that's the most immediate, specific problem the audit found.",
    conversion_leak: "The site exists but the audit found broken conversion paths. The angle leads with the specific finding to demonstrate you did your homework, not a generic pitch.",
    trust_deficit: "Review count is below what's competitive in this market. The angle leads with a specific comparison because it's concrete and immediately understood by the owner.",
    missed_revenue: "This business has real equity but isn't capturing the digital revenue their quality deserves. The angle leads with the gap, not the problem — more motivating for an established owner.",
    competitive_threat: "Competitive environment creates external pressure. The angle leads with what's happening externally rather than what's broken internally — more galvanizing for skeptical owners."
  };
  const CTA_EXPLANATIONS = {
    audit_offer: `Score tier (${score_tier}) suggests a softer entry point. The audit offer reduces the perceived cost of saying yes.`,
    quick_win_demo: "High priority score warrants a direct offer. A 15-minute demo of one specific improvement is specific enough to feel credible and short enough to feel low-risk.",
    free_strategy_call: "Top-tier lead with high aggressiveness setting. A direct calendar ask is appropriate — the score justifies the directness.",
    benchmark_report: "High score with missed revenue angle. A competitive benchmark is immediately relevant and positions you as someone who did research.",
    no_cost_assessment: "Lower-tier lead where value needs to be established first. The assessment framing provides something concrete to respond to."
  };
  const predictedResponseRate = () => {
    if (score_tier === "priority" && top_audit_signals.length >= 3)
      return "high";
    if (score_tier === "high" && top_audit_signals.length >= 2)
      return "above_average";
    if (score_tier === "medium") return "average";
    return "below_average";
  };
  return {
    why_this_angle: `${ANGLE_EXPLANATIONS[recommended_offer_angle]} ${CTA_EXPLANATIONS[score.recommended_cta]}`,
    what_audit_data_drove_it: top_audit_signals.slice(0, 3),
    framework_used: ANGLE_FRAMEWORK_MAP[recommended_offer_angle].join(" · "),
    what_to_watch: "Look for replies that reference the specific observation — that signals genuine interest. A 'who are you?' reply still means they read it. No reply to email 2 likely means email timing or contact info is wrong, not that the message failed.",
    predicted_response_rate: predictedResponseRate(),
    personalization_depth_used: `Business name, city, niche, review count (${lead.reviewCount}), ${top_audit_signals.length} specific audit findings. Frameworks: ${frameworks.join(", ")}.`
  };
}
