function getNicheKey(niche) {
  const n2 = niche.toLowerCase().replace(/[^a-z]/g, "");
  if (n2.includes("plumb")) return "plumbing";
  if (n2.includes("medspa") || n2.includes("spa") || n2.includes("aesthetic"))
    return "medspa";
  if (n2.includes("hvac") || n2.includes("heat") || n2.includes("cool") || n2.includes("air"))
    return "hvac";
  if (n2.includes("restor") || n2.includes("water") || n2.includes("fire"))
    return "restoration";
  if (n2.includes("carpet") || n2.includes("clean")) return "carpet";
  if (n2.includes("roof")) return "roofing";
  if (n2.includes("real") || n2.includes("estate") || n2.includes("agent") || n2.includes("broker"))
    return "realestate";
  if (n2.includes("mortg") || n2.includes("loan")) return "mortgage";
  if (n2.includes("chiro")) return "chiro";
  if (n2.includes("dent")) return "dental";
  return "default";
}
function calculateFundabilityScore(inputs) {
  let score = 0;
  if (inputs.entityType === "llc" || inputs.entityType === "scorp" || inputs.entityType === "ccorp")
    score += 10;
  if (inputs.hasEin) score += 10;
  if (inputs.yearsInBusiness === "gt2") score += 10;
  else if (inputs.yearsInBusiness === "1to2") score += 5;
  if (inputs.hasBankAccount) score += 15;
  if (inputs.hasCommercialAddress) score += 10;
  if (inputs.hasBusinessPhone) score += 5;
  if (inputs.businessCreditCards === "2plus") score += 15;
  else if (inputs.businessCreditCards === "1") score += 10;
  if (inputs.hasGbpVerified) score += 10;
  if (inputs.hasActiveWebsite) score += 5;
  if (inputs.hasExistingLoc) score += 5;
  return Math.min(score, 100);
}
function getScoreTier(score) {
  if (score <= 30) return "pre-fundable";
  if (score <= 60) return "building";
  if (score <= 80) return "creditworthy";
  return "fundable";
}
